-- app_dp_relation 建表+导入数据（本地建档/导数据参考）
-- 注意：本表已纳入 AutoMigrate 自动建表（见 initialize/gorm.go 的 MysqlTables），服务启动即创建，生产无需执行本脚本。
-- 来源: upstream-appId-dp-relation-sample.json (100 条)

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `app_dp_relation` (
  `id`               BIGINT       NOT NULL COMMENT '主键',
  `del_flag`         TINYINT(1)   NOT NULL DEFAULT 0  COMMENT '删除标记',
  `create_time`      DATETIME     NULL COMMENT '创建时间',
  `update_time`      DATETIME     NULL COMMENT '更新时间',
  `project_type`     VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '项目类型(cloud)',
  `project_id`       VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '项目ID',
  `project_name`     VARCHAR(128) NOT NULL DEFAULT '' COMMENT '项目名称',
  `deploy_project_id`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '部署项目ID',
  `deploy_project_name` VARCHAR(128) NOT NULL DEFAULT '' COMMENT '部署项目名称',
  `node`             VARCHAR(128) NOT NULL DEFAULT '' COMMENT '节点(机房/地域)',
  `env`              INT          NOT NULL DEFAULT 0  COMMENT '环境(1=PRO)',
  `apollo_host_id`   INT          NOT NULL DEFAULT 0  COMMENT 'Apollo实例ID',
  `apollo_app_id`    VARCHAR(128) NOT NULL DEFAULT '' COMMENT 'Apollo AppID',
  `apollo_app_env`   VARCHAR(16)  NOT NULL DEFAULT '' COMMENT 'Apollo环境(PRO/SIT/DEV)',
  `apollo_app_cluster` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'Apollo集群名',
  `is_released`      TINYINT(1)   NOT NULL DEFAULT 0  COMMENT '是否已发布',
  `operation`        VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '操作类型(create/update)',
  `operator`         INT          NOT NULL DEFAULT 0  COMMENT '操作人ID',
  PRIMARY KEY (`id`),
  KEY `idx_project_id`   (`project_id`),
  KEY `idx_apollo_app_id` (`apollo_app_id`),
  KEY `idx_apollo_host`   (`apollo_host_id`),
  KEY `idx_env`           (`env`),
  KEY `idx_node`           (`node`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='app_id与部署项目关系表';


